class admin(object):
    """
    Usage example:
        >>> from taf.sbts.oam.coam.admin import admin
        >>> api = admin()
        >>> connection = api.connect_to()
        >>> result = connection.get_bts_info()
        >>> result["id"]["internal"]
        "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1"

    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope("connection", AdminConnection)

    def __init__(self):
        self.lookup_handler.store = self.store
        self.ROBOT_LIBRARY_LISTENER = _CloseListener(self.teardown_all_aliases_for_admin)

    def _extract_connection_from_alias(func):
        """ 4G uses alias parameter not connection """
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            bool_array = [str(arg).startswith("alias=") for arg in args]
            is_alias_in_args = any(bool_array)
            if "alias" in dict(kwargs):
                kwargs["connection"] = kwargs["alias"]
                kwargs.pop("alias")
            elif is_alias_in_args:
                alias_expression = args[bool_array.index(True)]
                alias = alias_expression[alias_expression.index('=') + 1:]
                kwargs["connection"] = alias
                args = list(args)
                args.pop(bool_array.index(True))
            else:
                for index, arg in enumerate(list(args)):
                    if arg in [item[0] for item in self.store.all]:
                        kwargs["connection"] = arg
                        args = args[:index] + args[index + 1:]
            kwargs.pop("alias", None)
            return func(self, *args, **kwargs)

        return wrapper

    def connect_to(self,
                   bts_host="192.168.255.129",
                   bts_port=443,
                   username="Nemuadmin",
                   password="nemuuser",
                   use_ssl=True,
                   update_interval=5000,
                   admin_api_log_dir="",
                   name="default",
                   bundle_path=None,
                   release=None,
                   timeout=30,
                   trim_logs=False,
                   user_node_path=None
                   ):
        """
        Connect to Node B.

        :param str bts_host: BTS IP address.
        :param Union[int,str] bts_port: AdminAPI port.
        :param str username: AdminAPI username.
        :param str password: AdminAPI password.
        :param bool use_ssl: use SSL.
        :param Union[int,str] update_interval: The minimum updates interval in [ms].
        :param str admin_api_log_dir: AdminAPI log dir
        :param str name: (Optional) Name of returned connection. It not provided, this connection becomes default.
        :param str bundle_path: (Optional) Path to alternative or knife bundle.js provided by ADMIN
        :param str release: Name of coam admin interface version. Available releases: SBTS21B, SBTS22R1, SBTS22R2,
            SBTS22R3, SBTS22R4, SBTS23R1, SBTS23R2, SBTS23R3, SBTS23R4, SBTS24R1, SBTS24R2, SBTS24R3, SBTS25R1,
            SBTS25R2, SBTS25R3, SBTS26R1, SBTS26R2, SBTS00.
            If release parameter is not set (None by default) or set as SBTS00 it will
            automatically check current software release version. If user expects from the library that interface is stable,
            always specify release version in your code.
        :param bool trim_logs: Reduces the amount of debug prints in the log.
        :param string user_node_path: User defined path to node.js.
        :param Union[int,str] timeout: Time to wait for Admin API setup
        :return: Instance object of AdminConnection
        """

        connection = AdminConnection(
            bts_host=bts_host,
            bts_port=bts_port,
            username=username,
            password=password,
            use_ssl=to_boolean(use_ssl),
            update_interval=update_interval,
            admin_api_log_dir=admin_api_log_dir,
            name=name,
            bundle_path=bundle_path,
            release=release,
            timeout=time_to_seconds(timeout, round_to=0),
            trim_logs=to_boolean(trim_logs),
            user_node_path=user_node_path
        )

        self.store.add(connection, name)
        return connection

    def setup_admin(self,
                    bts_host="192.168.255.129",
                    bts_port=443,
                    username="Nemuadmin",
                    password="nemuuser",
                    use_ssl=True,
                    update_interval=5000,
                    admin_api_log_dir="",
                    bundle_path=None,
                    remote_host=None,
                    remote_host_username="ute",
                    remote_host_password="ute",
                    timeout=30,
                    name="default",
                    release=None,
                    trim_logs=False,
                    user_node_path=None,
                    **kwargs):
        """Setup Admin API.

        :param string bts_host: BTS IP address.
        :param integer bts_port: AdminAPI port.
        :param string username: AdminAPI username.
        :param string password: AdminAPI password.
        :param boolean use_ssl: use SSL, after PR515918 unsecure connection is not allowed.
        :param integer update_interval: The minimum updates interval in [ms].
        :param string admin_api_log_dir: AdminAPI log directory.
        :param string bundle_path: Custom bundle.js path.
        :param string remote_host: remote host ip address for SSH tunneling. None means disabled SSH tunneling.
                                    Do not use when eNB is connected to local machine!
        :param string remote_host_username: Username for remote host SSH authentication. Default is 'ute'.
        :param string remote_host_password: Password for remote host SSH authentication. Default is 'ute'.
        :param float timeout: Time to wait for Admin API setup.
        :param string name: Name of returned connection. It not provided, this connection becomes default.
        :param str release: Name of coam admin interface version. Available releases: SBTS21B, SBTS22R1, SBTS22R2,
            SBTS22R3, SBTS22R4, SBTS23R1, SBTS23R2, SBTS23R3, SBTS23R4, SBTS24R1, SBTS24R2, SBTS24R3, SBTS25R1,
            SBTS25R2, SBTS25R3, SBTS26R1, SBTS26R2, SBTS00.
            If release parameter is not set (None by default) or set as SBTS00 it will
            automatically check current software release version. If user expects from the library that interface is stable,
            always specify release version in your code.
        :param bool trim_logs: Reduces the amount of debug prints in the log.
        :param string user_node_path: User defined path to node.js.
        :raise AliasInUse: If name already exist in AliasStore.
        :return: Instance object of AdminConnection
        """
        if "alias" in kwargs.keys() and name == "default":
            name = kwargs["alias"]
        if name in [item[0] for item in self.store.all]:
            raise AliasInUse("Alias ({}) exists. Please remove it to reuse.".format(name))

        use_ssl = to_boolean(use_ssl)
        timeout = time_to_seconds(timeout)
        trim_logs = to_boolean(trim_logs)

        connection = AdminConnection(
            bts_host=bts_host,
            bts_port=int(bts_port),
            username=username,
            password=password,
            use_ssl=to_boolean(use_ssl),
            update_interval=update_interval,
            admin_api_log_dir=admin_api_log_dir,
            name=name,
            bundle_path=bundle_path,
            release=release,
            remote_host=remote_host,
            remote_host_username=remote_host_username,
            remote_host_password=remote_host_password,
            timeout=time_to_seconds(timeout, round_to=0),
            trim_logs=trim_logs,
            user_node_path=user_node_path
        )

        self.store.add(connection, name)
        return connection

    @_extract_connection_from_alias
    @lookup_handler.implicit_lookup
    def teardown_admin(self, connection=None, **kwargs):
        """
        Disconnects and destroys node.js daemon

        :param Union[AdminConnection,str] connection: AdminConnection object or if used, string name alias.
        """
        self.teardown(connection)

    def teardown_all_aliases_for_admin(self):
        """Cleanup all AdminConnection."""
        for connection in [item[1] for item in self.store.all]:
            self.teardown(connection)

    @_extract_connection_from_alias
    @lookup_handler.implicit_lookup
    def reset_admin(self, connection=None, **kwargs):
        """Reset Admin API.

        :param Union[AdminConnection,str] connection: AdminConnection object or if used, string name alias.
        """
        connection.api_reset()

    @_extract_connection_from_alias
    @lookup_handler.implicit_lookup
    def get_bts_info(self, timeout=20, connection=None, detailed_output=False, **kwargs):
        """
        Keyword for getting BTS general information from Node B

        :param Union[int,str] timeout: Keyword execution timeout.
        :param Union[AdminConnection,str] connection: AdminConnection object or if used, string name alias.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return: Dictionary with data. More details (content of requestMessage is returned data):
                 https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getBtsInformation.html
        """
        return connection.get_bts_info(timeout=time_to_seconds(timeout, round_to=0),
                                       detailed_output=to_boolean(detailed_output))

