    @lookup_handler.implicit_lookup
    def get_snapshot(self, target_file_name, coverage="Full", force=True, timeout=360, connection=None,
                     reg_exp_filter=None, reason=None, network_cell_dns=None, detailed_output=False):
        """
        Order snapshot creation, collection and save it in local path.

        :param str target_file_name: Location where snapshot shall be saved.
        :param str coverage: Full, Minor or HealthCheck (only for SRAN) snapshot scope. defaults set to Full.
        :param bool force: True or False to force snapshot creation.
        :param Union[int,str] timeout: Timeout for the operation. Note: CLI request for snapshot is not cancelled after timeout.
                            For cancel please call snapshot_cancel()
        :param AdminConnection connection: AdminConnection object.
        :param str reg_exp_filter: optional) since SBTS18, "regExpFilter" will be ignored if coverage is"HealthCheck"
        :param str reason: (optional) reason for the operation.
        :param list[str] network_cell_dns: (optional) list of str of network cell dist names (only for SRAN builds)
        :param bool detailed_output: return full request response when True, defaults set to False.
        :raises AdminApiProcedureFailureException: If response status equals 'failed' it returns that exception.

        :return str: Status of the operation.
                      More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-snapshot.html
        """
        return connection.get_snapshot(target_file_name=target_file_name, coverage=coverage, force=to_boolean(force),
                                       timeout=time_to_seconds(timeout, round_to=0), reg_exp_filter=reg_exp_filter,
                                       reason=reason, network_cell_dns=network_cell_dns,
                                       detailed_output=to_boolean(detailed_output))

