    @_extract_connection_from_alias
    @lookup_handler.implicit_lookup
    def perform_parameter_recommissioning(self, dist_name, parameter, operation, value,
                                          skip_parameter_relation_errors=False, should_activate=True,
                                          timeout=300, connection=None, **kwargs):
        """
        Perform parameter recommissioning, update and delete operation can be used.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param string dist_name: Object dist name ie. "MRBTS-1/LNBTS-1/LNMME-0"
        :param string parameter: Parameter name ie. "ipAddrPrim"
        :param string operation: Parameter operation, update or delete can be choosen
        :param Union[str,list] value: Parameter value ie. "10.0.1.99" or [{"eea1":0, "eea0":1, "eea3":8, "eea2":0}]
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :param Union[AdminConnection,str] connection: AdminConnection object or if used, string name alias.
        :raises taf.sbts.oam.coam.admin.legacy.exceptions.AdminApiProcedureFailureException: Will be raised if
            recommissioning fails
        :return dict: Recommissioning status
                More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-recommission.html

        For example, dict as blow will be returned if recommission success

        ::

            {
                'commissioningResult': {
                     'isGoingToTriggerReset': False,
                     'activationResult': {
                         'resultNode': {
                             'distName': '/MRBTS-1/RAT-1/URI-1/SESSION-17/PLAN_ACTIVATE_IND-1/PLAN_ACTIVATE_RESULT-1',
                             'parameters': {
                                 'rejectedObjects': [],
                                 'resetCoverage': 'None',
                                 'result': 'Success'
                                 }
                            },
                        'indicationDistName': '/MRBTS-1/RAT-1/URI-1/SESSION-17/PLAN_ACTIVATE_IND-1'
                     }
                 },
                'validationResult': {
                    'niddValidationResult': {
                        'status': 'OK',
                        'logs': {
                            'skippedElements': None,
                            'missingObjectsErrors': None,
                            'definitionErrors': None,
                            'maxOccurrencesErrors': None
                        }
                    },
                    'pdlValidationResult': {
                        'status': 'OK',
                        'logs': {
                            'hardwareErrors': [],
                            'relationErrors': []
                        }
                    }
                },
                'modifiedObjectsDistNames': {
                     'deleted': [],
                     'modified': ['MRBTS-111/LNBTS-1/LNADJGNB-1']
                }
            }

        To update one parameter like below:

        1) To update value of "pMaxOwnCell" to 24, value type is str
        admin.perform_parameter_recommissioning(
            dist_name="MRBTS-111/LNBTS-40/LNCEL-11/SIB-0",
            parameter="pMaxOwnCell",
            value="24",
            operation="update",
            skip_parameter_relation_errors=True

        2) To update values of "cipherPrefL" as a list, value type is list
        admin.perform_parameter_recommissioning(
            dist_name="MRBTS-111/LNBTS-40",
            parameter="cipherPrefL",
            value=[{"eea0": 0, "eea1": 0, "eea2": 0, "eea3": 0}],
            operation="update",
            skip_parameter_relation_errors=True
        )

        Like above, operation="delete" can delete one parameter or list of parameters.
        """
        return connection.perform_parameter_recommissioning(
            dist_name=dist_name, parameter=parameter, operation=operation, value=value,
            skip_parameter_relation_errors=to_boolean(skip_parameter_relation_errors),
            should_activate=to_boolean(should_activate),
            timeout=time_to_seconds(timeout, round_to=0)
        )

    @lookup_handler.implicit_lookup
    def perform_object_recommissioning(self, dist_name, parameter, operation,
                                       skip_parameter_relation_errors=False, should_activate=True,
                                       timeout=300, connection=None):
        """
        Perform object recommissioning, create, update and delete operation can be used.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param string dist_name: Object dist name ie. "MRBTS-111/LNBTS-40/LNCEL-11/LNRELGNBCELL-0"
        :param list parameter: list of dicts, as empty list to delete object
        :param string operation: Object operation, create, update or delete can be choosen
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param bool should_activate: Should automatically activate plan
        :param Union[int,str] timeout: Time to wait for positive procedure result
        :param AdminConnection connection: AdminConnection object.
        :raises taf.sbts.oam.coam.admin.legacy.exceptions.AdminApiProcedureFailureException: Will be raised if
            recommissioning fails
        :return dict: Recommissioning status
                More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-recommission.html

        1) To delete one object: ("parameter=[]" and "operation='delete'" are needed):

        admin.perform_object_recommissioning(
            dist_name="MRBTS-111/LNBTS-40/LNCEL-11/LNRELGNBCELL-0",
            parameter=[],
            operation="delete",
            skip_parameter_relation_errors=True
        )

        2) To create one object: (parameters and "operation='create' are needed")

        parameter = [
            {
                "parameterName": "gnbIdLength",
                "operation": "update",
                "value": 22
            },
            {
                "parameterName": "lteNrDualConnectAllowed",
                "operation": "update",
                "value": "allowed"
            },
            {
                "parameterName": "nrCellId",
                "operation": "update",
                "value": 32765
            },
            {
                "parameterName": "nrCgiPlmnId",
                "operation": "update",
                "value": [
                    {
                        "mcc": 262,
                        "mnc": 3,
                        "mncLength": 2
                    }
                ]
            }
        ]
        admin.perform_object_recommissioning(
            dist_name="MRBTS-111/LNBTS-40/LNCEL-11/LNRELGNBCELL-0",
            parameter=parameters,
            operation="create",
            skip_parameter_relation_errors=True
        )

        """
        return connection.perform_object_recommissioning(
            dist_name=dist_name, parameter=parameter, operation=operation,
            skip_parameter_relation_errors=to_boolean(skip_parameter_relation_errors),
            should_activate=to_boolean(should_activate),
            timeout=time_to_seconds(timeout, round_to=0)
        )

