    @lookup_handler.implicit_lookup
    def start_5g_uplink_test(self, dist_name, frc_index, beam_pattern_id,
                             interval, prb_offset, ru_mode, phys_cell_id,
                             nrarfcn_ul=None, nrarfcn_dl=None, timeout=60, connection=None):
        """
        Starts 5G Uplink Test.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param str frc_index: One of the following: `G_FR1_A1_1`, `G_FR1_A1_2`,
                                `G_FR1_A1_4`, `G_FR1_A1_5`, `G_FR1_A1_7`, `G_FR1_A2_1`,
                                `G_FR1_A2_4`, `G_FR1_A2_5`, `GFR2_A1_2`, `G_FR2_A1_3`.
        :param List[Union[int,str]] beam_pattern_id: [0..1200].
        :param Union[float,str] interval: Reporting time interval [1..3600]
        :param Union[int,str] prb_offset: [0..273]
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param Union[int,str] phys_cell_id: [0..1007].
        :param Union[int,str] nrarfcn_ul: (Optional) [0..3279165]
        :param Union[int,str] nrarfcn_dl: (Optional) [0..3279165]
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param AdminConnection connection: AdminConnection object.
        :return: It returns dict with data.

        Example response

        ::

            {
              "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0",
              "confirmationNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0/ACK-1",
                 "parameters": {}
              },
              "resultNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0/NR_TEST_RESULT-1",
                 "parameters": {
                    "status": "Succeeded"
                 }
                }
            },

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-start5GUplinkTest.html

        """
        if not isinstance(beam_pattern_id, list):
            raise TypeError('Parameter beam_pattern_id should be list type not {}'
                            .format(type(beam_pattern_id)))

        beam_pattern_id = [int(element) for element in beam_pattern_id]
        interval = float(interval)
        prb_offset = int(prb_offset)
        phys_cell_id = int(phys_cell_id)
        nrarfcn_ul = int(nrarfcn_ul) if nrarfcn_ul is not None else None
        nrarfcn_dl = int(nrarfcn_dl) if nrarfcn_dl is not None else None

        return connection.start_5g_uplink_test(dist_name=dist_name,
                                               frc_index=frc_index,
                                               beam_pattern_id=beam_pattern_id,
                                               interval=interval,
                                               prb_offset=prb_offset,
                                               ru_mode=ru_mode,
                                               phys_cell_id=phys_cell_id,
                                               nrarfcn_ul=nrarfcn_ul,
                                               nrarfcn_dl=nrarfcn_dl,
                                               timeout=time_to_seconds(timeout, round_to=0))

