    def change_beam_pattern_id(self, test_dn, beam_pattern_id, timeout=10, connection=None):
        """
        .. note::
            SUPPORTS INTERNAL API ONLY

        :param str test_dn:  DistName of target test
        :param List[Union[int,str]] beam_pattern_id:  List of Ids of beam pattern <0 to 1200> (two items at most)
        :param Union[int,str] timeout: (optional) Timeout for the operation, defaults to 10
        :param AdminConnection connection: AdminConnection object.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        :raises AdminApiProcedureFailureException: If responseStatus equals 'failed' it returns that exception.

        :return str: Status of the operation.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-changeBeamPatternId.html

        """
        if not isinstance(beam_pattern_id, list):
            raise TypeError('Parameter beam_pattern_id should be list type not {}'
                            .format(type(beam_pattern_id)))

        beam_pattern_id = [int(element) for element in beam_pattern_id]

        return connection.change_beam_pattern_id(test_dn, beam_pattern_id, timeout=time_to_seconds(timeout, round_to=0))

