    @_extract_connection_from_alias
    @lookup_handler.implicit_lookup
    def start_uplink_test(self, dist_name, reference_channel_number, reporting_time_interval, resource_block_offset,
                          earfcn, digital_output_type, enable_harq=None, enable_digital_output=None, bit_rate=None,
                          bb_selector=None, hst_config=None, resource_index_cqi=None, enable_dli_interference=None,
                          tdd_frame_conf=None, tdd_spec_subf_conf=None, nb_subcarrier_index=None, measured_frc=None,
                          reference_channel_number_nb_linked=None, local_cell_res_id_nb_linked=None,
                          inband_prb_index_ul=None, guardband_index_ul=None, timeout=60, connection=None,
                          nb_repetitions=None, nb_subframe_offset=None, **kwargs):

        """
        Start LTE uplink test.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param str dist_name: LNCEL_R object to perform test on
        :param str reference_channel_number: reference_channel_number. One of the following:
                                             "Invalid", "A1_1", "A1_2",
                                             "A1_3", "A1_4", "A1_5",
                                             "A1_6", "A1_7", "A1_8",
                                             "A1_9", "A2_1", "A2_2",
                                             "A2_3", "A2_4", "A2_5",
                                             "A3_1", "A3_2", "A3_3",
                                             "A3_4", "A3_5", "A3_6",
                                             "A3_7", "A4_1", "A4_2",
                                             "A4_3", "A4_4", "A4_5",
                                             "A4_6", "A4_7", "A4_8",
                                             "A5_1", "A5_2", "A5_3",
                                             "A5_4", "A5_5", "A5_6",
                                             "A5_7", "A7_1", "A7_2",
                                             "A7_3", "A7_4", "A7_5",
                                             "A7_6", "A8_1", "A8_2",
                                             "A8_3", "A8_4", "A8_5",
                                             "A8_6", "A14_1", "A15_1",
                                             "DCM_1", "DCM_2", "DCM_3",
                                             "DCM_4", "DCM_5", "DCM_6",
                                             "DCM_7", "DCM_8", "A16_2",
                                             "A16_3", "A16_4", "A16_5",
                                             "A17_1", "A17_2", "A17_3",
                                             "A17_4", "A17_5", "A17_6"
        :param Union[int,str] reporting_time_interval: reporting_time_interval <0 to 4294967295>
        :param Union[int,str] resource_block_offset: resource_block_offset <0 to 99>
        :param Union[int,str] earfcn: earfcn <0 to 262143>
        :param str digital_output_type: digitalOutputType. One of the following: "BinaryHarq", "SerialAgilent",
                                                                                 "SerialRs"
        :param boolean enable_harq: (Optional) enable_harq: True or False
        :param boolean enable_digital_output: (Optional) enable_digital_output: True or False
        :param str bit_rate: (Optional) bit_rate. One of the following: "115Dot2Kbps", "460Dot8Kbps", "1Dot92Mbps"
        :param str bb_selector: (Optional) bb_selector: One of the following: "00", "01", "10", "11"
        :param str hst_config: (Optional) hst_config: One of the following: "NotApplied", "HstScenario1",
                                                      "HstScenario3", "HstPucchScenario1", "HstPucchScenario3"
        :param Union[int,str] resource_index_cqi: (Optional) resource_index_cqi <0 to 1185>
        :param boolean enable_dli_interference: (Optional) enable_dli_interference: True or False
        :param Union[int,str] tdd_frame_conf: (Optional) tdd_frame_conf <1 to 3>
        :param Union[int,str] tdd_spec_subf_conf: (Optional) tdd_spec_subf_conf <3 to 9>
        :param Union[int,str] nb_subcarrier_index: (Optional) nb_subcarrier_index <0 to 47>
        :param str measured_frc: (Optional in general, but mandatory if ulTestModelNbLinked). One of the following:
                                 "nbLinked", "both", "1Dot92Mbps"
        :param str reference_channel_number_nb_linked: (Optional in general, but mandatory if ulTestModelNbLinked).
                                                        One of the following: "A14_1", "A15_1", "A16_2",
                                                                              "A16_3", "A16_4", "A16_5"
        :param Union[int,str] local_cell_res_id_nb_linked: (Optional in general, but mandatory if ulTestModelNbLinked)
                                                <0 to 4294967295>
        :param Union[int,str] inband_prb_index_ul: (Optional if ulTestModelNbLinked) <0 to 99>
        :param str guardband_index_ul: (Optional if ulTestModelNbLinked). One of following:
                                        "undefined", "plus4590kHz", "plus6840kHz", "plus9090kHz", "minus4590kHz",
                                        "minus6840kHz", "minus9090kHz"
        :param Union[int,str] timeout: (optional) Timeout for the operation. Defaults set to 60s.
        :param Union[AdminConnection,str] connection: AdminConnection object or if used, string name alias.
        :param str nb_repetitions: (Optional) One of the following: "NBR_1", "NBR_2", "NBR_16", "NBR_64"
        :param int nb_subframe_offset: (Optional) <0 to 255>

        :return: It returns dict with data.

        Example response:
        {
            "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_LTE_UPLINK_TEST_IND-0",
            "confirmationNode": {
                "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_LTE_UPLINK_TEST_IND-0/ACK-1",
                "parameters": {}
            },
            "resultNode": {
                "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_LTE_UPLINK_TEST_IND-0/LTE_TEST_RESULT-1",
                "parameters": {
                    "status": "Succeeded",
                    "cause":null
                }
            }
        }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-startLteUplinkTest.html
        """

        reporting_time_interval = int(reporting_time_interval)
        resource_block_offset = int(resource_block_offset)
        earfcn = int(earfcn)
        enable_harq = to_boolean(enable_harq) if enable_harq is not None else None
        enable_digital_output = to_boolean(enable_digital_output) if enable_digital_output is not None else None
        resource_index_cqi = int(resource_index_cqi) if resource_index_cqi is not None else None
        enable_dli_interference = to_boolean(enable_dli_interference) if enable_dli_interference is not None else None
        tdd_frame_conf = int(tdd_frame_conf) if tdd_frame_conf is not None else None
        tdd_spec_subf_conf = int(tdd_spec_subf_conf) if tdd_spec_subf_conf is not None else None
        nb_subcarrier_index = int(nb_subcarrier_index) if nb_subcarrier_index is not None else None
        local_cell_res_id_nb_linked = int(local_cell_res_id_nb_linked) if local_cell_res_id_nb_linked is not None \
            else None
        inband_prb_index_ul = int(inband_prb_index_ul) if inband_prb_index_ul is not None else None
        nb_subframe_offset = int(nb_subframe_offset) if nb_subframe_offset is not None else None

        return connection.start_uplink_test(dist_name=dist_name,
                                            reference_channel_number=reference_channel_number,
                                            reporting_time_interval=reporting_time_interval,
                                            resource_block_offset=resource_block_offset,
                                            earfcn=earfcn,
                                            enable_harq=enable_harq,
                                            enable_digital_output=enable_digital_output,
                                            digital_output_type=digital_output_type,
                                            bit_rate=bit_rate,
                                            bb_selector=bb_selector,
                                            hst_config=hst_config,
                                            resource_index_cqi=resource_index_cqi,
                                            enable_dli_interference=enable_dli_interference,
                                            tdd_frame_conf=tdd_frame_conf,
                                            tdd_spec_subf_conf=tdd_spec_subf_conf,
                                            nb_subcarrier_index=nb_subcarrier_index,
                                            measured_frc=measured_frc,
                                            reference_channel_number_nb_linked=reference_channel_number_nb_linked,
                                            local_cell_res_id_nb_linked=local_cell_res_id_nb_linked,
                                            inband_prb_index_ul=inband_prb_index_ul,
                                            guardband_index_ul=guardband_index_ul,
                                            timeout=time_to_seconds(timeout, round_to=0),
                                            nb_repetitions=nb_repetitions,
                                            nb_subframe_offset=nb_subframe_offset, **kwargs)

