    def run_keyword_in_background(self, name, *args, **kwargs):
        """
        Runs keyword in a separate thread. Requires additional AdminApi connection.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param string name: Keyword name to execute in background.
        :rtype: AsyncTask
        :return: task object - executed keyword thread wrapper.

        **WARNING!** This library is not thread-safe. In order to avoid race condition, new connection
         (other that the one that is currently in use) should be passed as a given keyword argument.
        """
        task = AsyncTask(self, name, *args, **kwargs)
        task.start()

        return task

    def collect_keyword_result(self, task, timeout=120):
        """
        Collects result of keyword that was run in background.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param AsyncTask task: Task object - executed keyword thread wrapper.
        :param Union[str, int] timeout: (optional) Timeout for the operation, 120s by default.
        :return: Keyword result.
        :raises: Keyword execution error.

        **WARNING**
         This timeout 'overrides' the one passed while running the keyword (in background). An exception will be raised
         if the keyword has not finished at the time collection timeout expires. If the collection is performed immediately
         after running the keyword (in background) following condition should be true:
         collection timeout >= keyword's timeout
        """

        return task.collect_result(timeout=time_to_seconds(timeout, round_to=0))

