    @_extract_connection_from_alias
    @lookup_handler.implicit_lookup
    def assert_(self, class_name, id, parameters=None, timeout=10, connection=None, **kwargs):
        """
        Assert that item exists and matches given parameters.

        .. note::
            SUPPORTS INTERNAL API ONLY

        :param string class_name: "RMOD", "ASIRMOD", "SMOD", "BBU", "ALD", "LNCEL", "WNCEL", "GNCEL", "NRCEL", "BBMOD",
                                  "LNMME", "RNC", "BSC", "SFP", "LNADJ", "NRADJ", "LNBTS", "SMOD_EXT", "CABLINK", "BTS",
                                  "CABINET", "CARRIERGROUPC", "FHS"
        :param string id: item ID
        :param string parameters: Required item parameters. None means no parameter value validation.
        :param Union[int,str] timeout: Time to wait for matching item.
        :param Union[AdminConnection,str] connection: AdminConnection object or if used, string name alias.

        :return dict: dict with class name info

        More info at https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-subscribeForParameters.html

        |

        **PARAMETERS syntax:**
            - PARAMETER1 OPERATOR1 VALUE1, PARAMETER2 OPERATOR2 VALUE2, ...
                * example: status=disabled, temperature>100, temperature<=120
                * single spaces between elements are allowed with one exception - see empty VALUE
            - PARAMETERs:
                * simple: temperature, status, etc.
                * nested: stateInfo.availabilityStatus, etc.
                * lists: alarms[5], stateInfo.reasoningStatus[?], alarms[*]
                    * \\* means all elements
                    * ? means any element
            - OPERATORs: >, <, >=, <=, =, !=
            - VALUEs:
                * literal: 5, disabled
                * regex:
                    * positive match: parameter=regex"[Oo]nline"
                    * negative match: parameter!=regex"validated|onAirDone"
                * empty: string 'empty' is interpreted as an empty value, but there may be no space before it
                    * correct: parameter=empty, parameter !=empty
                    * incorrect: parameter = empty

        |

        """  # noqa: W605

        if parameters:
            return connection.check_if_(class_name=class_name, id=id, parameters=parameters,
                                        timeout=time_to_seconds(timeout, round_to=0))
        else:
            parameters = []
            if 'parameters' in kwargs.keys():
                parameters.append(kwargs.pop('parameters'))
            for item in kwargs:
                parameters.append(str(item) + "=" + str(kwargs[item]))
            if parameters:
                parameters = ', '.join(parameters)
            else:
                parameters = None
            return connection.check_if_(class_name=class_name, id=id, parameters=parameters,
                                        timeout=time_to_seconds(timeout, round_to=0))

